function drawScanProgress(){if(!scanContext||!latestScanJob||latestScanJob.id!==scanContext.jobId)return;document.querySelectorAll('[data-scan-progress]').forEach(element=>{if(compOwner(element.dataset.scanProgress)!==element.dataset.scanProgress){element.hidden=true;element.innerHTML='';return;}const ids=scanContext.assignments[element.dataset.scanProgress];if(!ids?.length){element.hidden=true;return;}const info=PricingMath.scanProgress(latestScanJob,ids,scanContext.due),running=latestScanJob.status==='running';element.hidden=false;element.classList.toggle('scan-has-errors',info.errors>0||latestScanJob.status==='failed');const text=running?'Scanning '+info.percent+'% · '+info.done+'/'+info.total:latestScanJob.status==='failed'?'Scan stopped · '+info.done+'/'+info.total:info.errors?'Finished · '+info.errors+' failed':'Saved · 100%';element.innerHTML='<div class="scan-label">'+text+'</div><progress max="100" value="'+info.percent+'" aria-label="'+esc(text)+'"></progress>';});}
$('confirmScan').onclick=()=>task($('confirmScan'),async()=>{if(!state.connections.airroi){$('scanDialog').close();openApiSettings();throw Error('Set your AirROI key in Settings → API keys before scanning.');}if(!scanPlan)throw Error('Please wait for the scan cost.');const plan=scanPlan,job=await post('/scan',{planId:plan.id,maxCost:plan.estimatedCost,confirm:true});const assignments={};for(const id of plan.propertyIds){const ids=compAssignments(id).filter(compId=>plan.ids.includes(compId));if(ids.length)assignments[id]=ids;}scanContext={jobId:job.id,due:plan.due,assignments};try{localStorage.setItem('oceanPricingScanContext',JSON.stringify(scanContext));}catch{}latestScanJob=job;estimateSequence++;invalidatePlan();$('scanDialog').close();drawScanProgress();notice('Scan started in the background. You can keep working on other properties.');watchJob(job.id).catch(error=>notice(error.message));}).finally(()=>{$('confirmScan').disabled=!scanPlan;});
async function watchJob(id){if(watchingScans.has(id))return;watchingScans.add(id);let job;try{do{job=await api('/scan?id='+encodeURIComponent(id));latestScanJob=job;drawScanProgress();if(job.status==='running')await new Promise(resolve=>setTimeout(resolve,1000));}while(job.status==='running');monthViews.clear();await loadSavedOwn();await refreshState();if(selected)await loadView();notice(job.errors.length?'Scan finished with '+job.errors.length+' error(s). Saved results were kept.':'Scan complete. Competitor results are saved.');}finally{watchingScans.delete(id);}}

