let settingsDraft=new Set(),settingsOrder=[];
const settingsButton=document.createElement('button');settingsButton.id='settings';settingsButton.className='plain-btn';settingsButton.textContent='Settings';document.querySelector('.top-actions').prepend(settingsButton);
let draggedProperty=null;
function moveSettingsProperty(source,target,after=false){if(!source||source===target)return;const next=settingsOrder.filter(id=>id!==source);const index=next.indexOf(target);if(index<0)return;next.splice(index+(after?1:0),0,source);settingsOrder=next;drawSettings();$('settingsMessage').textContent='Order changed. Click Save settings to keep it.';}
function drawSettings(){
 const query=$('settingsSearch').value.toLowerCase(),visible=orderedProperties(settingsOrder).filter(p=>(p.name+' '+p.address).toLowerCase().includes(query));
 $('settingsProperties').innerHTML=visible.map(p=>'<div class="settings-row" data-order-id="'+esc(p.id)+'"><button type="button" class="drag-handle" draggable="false" data-drag-id="'+esc(p.id)+'" aria-label="Drag '+esc(p.name)+' to reorder" title="Drag to reorder; or use arrow keys">⠿</button><label class="checkbox"><input type="checkbox" data-include="'+esc(p.id)+'" '+(settingsDraft.has(p.id)?'checked':'')+'><span><strong>'+esc(p.name)+'</strong><small>'+(p.bedrooms===0?'Studio':esc(p.bedrooms)+' bedrooms')+' · '+compAssignments(p.id).length+'/5 comps</small>'+(compOwner(p.id)!==p.id?'<small>Shared from '+esc(state.properties.find(master=>master.id===compOwner(p.id))?.name)+'</small>':'')+'</span></label><button type="button" class="plain-btn" data-settings-comps="'+esc(p.id)+'">Edit comps</button></div>').join('')||'<p>No properties found. Import Guesty first.</p>';
 document.querySelectorAll('[data-drag-id]').forEach(handle=>{
  handle.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();handle.setPointerCapture(event.pointerId);const source=handle.dataset.dragId,startY=event.clientY;let target=null,after=false,moved=false;
   const clear=()=>{document.querySelectorAll('.dragging,.drop-before,.drop-after').forEach(row=>row.classList.remove('dragging','drop-before','drop-after'));handle.onpointermove=null;handle.onpointerup=null;handle.onpointercancel=null;};
   handle.onpointermove=ev=>{if(Math.abs(ev.clientY-startY)>5)moved=true;if(!moved)return;handle.closest('.settings-row').classList.add('dragging');const row=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-order-id]');document.querySelectorAll('.drop-before,.drop-after').forEach(r=>r.classList.remove('drop-before','drop-after'));target=row?.dataset.orderId||null;if(row){after=ev.clientY>row.getBoundingClientRect().top+row.offsetHeight/2;row.classList.add(after?'drop-after':'drop-before');}const box=$('settingsProperties').getBoundingClientRect();if(ev.clientY<box.top+45)$('settingsProperties').scrollTop-=18;else if(ev.clientY>box.bottom-45)$('settingsProperties').scrollTop+=18;};
   handle.onpointerup=()=>{clear();if(moved&&target)moveSettingsProperty(source,target,after);};handle.onpointercancel=clear;
  };
  handle.ondragstart=event=>{draggedProperty=handle.dataset.dragId;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',draggedProperty);handle.closest('.settings-row').classList.add('dragging');};
  handle.ondragend=()=>{draggedProperty=null;document.querySelectorAll('.dragging,.drop-before,.drop-after').forEach(row=>row.classList.remove('dragging','drop-before','drop-after'));};
  handle.onkeydown=event=>{if(!['ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const id=handle.dataset.dragId,index=visible.findIndex(p=>p.id===id),target=visible[index+(event.key==='ArrowUp'?-1:1)];if(target){moveSettingsProperty(id,target.id,event.key==='ArrowDown');document.querySelector('[data-drag-id="'+CSS.escape(id)+'"]').focus();}};
 });
 document.querySelectorAll('[data-order-id]').forEach(row=>{
  row.ondragover=event=>{if(!draggedProperty)return;event.preventDefault();event.dataTransfer.dropEffect='move';const after=event.clientY>row.getBoundingClientRect().top+row.offsetHeight/2;document.querySelectorAll('.drop-before,.drop-after').forEach(r=>r.classList.remove('drop-before','drop-after'));row.classList.add(after?'drop-after':'drop-before');const box=$('settingsProperties').getBoundingClientRect();if(event.clientY<box.top+45)$('settingsProperties').scrollTop-=18;else if(event.clientY>box.bottom-45)$('settingsProperties').scrollTop+=18;};
  row.ondrop=event=>{if(!draggedProperty)return;event.preventDefault();const id=draggedProperty;draggedProperty=null;moveSettingsProperty(id,row.dataset.orderId,event.clientY>row.getBoundingClientRect().top+row.offsetHeight/2);};
 });
 document.querySelectorAll('[data-include]').forEach(e=>e.onchange=()=>{if(e.checked)settingsDraft.add(e.dataset.include);else settingsDraft.delete(e.dataset.include);});
 document.querySelectorAll('[data-settings-comps]').forEach(e=>e.onclick=()=>{demo=false;selected=e.dataset.settingsComps;showComps();$('compDialog').showModal();});
}

