function renderExpandedCalendar(propertyId=null){
 const dates=days();let body='';
 for(const [index,p] of properties().entries()){
  if(propertyId&&p.id!==propertyId)continue;
  const sample=demo?sampleView(p):null,own=demo?new Map(sample.own.days.map(d=>[d.date,d])):ownRateMaps.get(p.id)||new Map();
  const comps=demo?sample.comps:compAssignments(p.id).map(id=>{
   const snapshot=['calendar','rates'].map(type=>savedBackup?.snapshots?.[id+':'+type]).filter(Boolean).sort((a,b)=>b.fetchedAt.localeCompare(a.fetchedAt))[0];
   return {...state.comps[id],id,snapshot};
  });
  const cell=(date,html,extra='')=>'<td class="'+(date===today()?'today-column ':'')+extra+'">'+html+'</td>';
  body+='<tr class="expanded-own '+(index%2?'shade-gray':'shade-white')+'"><th scope="row">'+esc(p.name)+(ratingProfile(ownAirbnbId(p)).rating?' ★'+ratingProfile(ownAirbnbId(p)).rating.toFixed(2):'')+'<small>'+(p.bedrooms===0?'Studio':(p.bedrooms??'—')+' br')+' · Clean '+fee(p.cleaningFee)+'</small></th>'+dates.map(date=>{const d=own.get(date);return cell(date,d?money(d.rate)+(d.locked?' 🔒':d.available===false?' ⊘':'')+minimumStay(d):'—',d?.available===false?'unavailable':'');}).join('')+'</tr>';
  const compMaps=comps.map(c=>new Map((c.snapshot?.days||[]).map(d=>[d.date,d])));
  for(const [i,c] of comps.entries())body+='<tr class="expanded-comp"><th scope="row">'+(c.url?'<a href="'+esc(c.url)+'" target="_blank" rel="noopener noreferrer" title="'+esc(c.name)+'">'+esc(c.name)+'</a>':esc(c.name||c.id))+'<small>Cleaning: '+fee(c.snapshot?.cleaningFee)+'</small></th>'+dates.map(date=>{const d=compMaps[i].get(date);return cell(date,money(d?.rate)+(d?.available===false?' ⊘':'')+minimumStay(d),d?.available===false?'unavailable':'');}).join('')+'</tr>';
  body+='<tr class="expanded-suggested"><th scope="row">Suggested rate<small>AVG · within ±10%</small></th>'+dates.map(date=>{
   const d=own.get(date),row={current:d?.rate,booked:!d||d.available===false,locked:Boolean(d?.locked),comps:compMaps.map(map=>map.get(date)).filter(Boolean)};
   const result=String(p.currency||'').toUpperCase()==='USD'?PricingMath.propose(row,{mode:'match',percent:0,floor:1,ceiling:100000,minComps:1}):{proposed:null};
   const advice=PricingMath.advice(d?.rate,result.proposed),move=advice.move,cls=advice.css;
   return cell(date,move===null?'—':money(result.proposed)+'<small>'+advice.label+' '+advice.percent+'</small>',cls);
  }).join('')+'</tr>';
 }
 $('expandedCalendar').innerHTML='<thead><tr><th scope="col">Property / competitor</th>'+dates.map(date=>'<th scope="col" class="'+(date===today()?'today-column':'')+'"><small>'+new Date(date+'T00:00:00Z').toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'})+'</small>'+new Date(date+'T00:00:00Z').toLocaleDateString('en-US',{day:'numeric',month:'short',timeZone:'UTC'})+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody>';
}
