function ratingProfile(id,name=''){const numeric=Number((state.comps[id]?.listingTitle||name).match(/★\s*(\d(?:\.\d+)?)/)?.[1]);return savedBackup?.listingRatings?.[id]||savedBackup?.snapshots?.[id+':details']||{rating:numeric>0&&numeric<=5?numeric:null,isNew:/★\s*New\b/i.test(state.comps[id]?.listingTitle||name)};}
function metricIcon(title){
 const paths=title.includes('rating')?'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>':title.includes('nights')?'<path d="M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10Z"/>':title.includes('Booked')?'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 11h16m-11 5 2 2 4-4"/>':title.includes('Comp set')?'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m2 10v-3a6 6 0 0 0-2-4"/>':'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M12 8v8m3-6c-1-2-6-2-6 0s6 2 6 4-5 2-6 0"/>';
 return '<span class="metric-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+paths+'</svg></span>';
}
function windowComparisonCards(p,view,dates){
 const comparison=PricingMath.windowComparisons(dates,view.own?.days||[],view.comps,p.cleaningFee),stay=comparison.minStay,clean=comparison.cleaning,availability=PricingMath.availabilityComparison(dates,view.own?.days||[],view.comps),night=v=>v===null?'—':Number(v.toFixed(1));
 const label=status=>({HIGH:'HIGH',LOW:'LOW',AVG:'AVG',MISSING:'NO DATA',SAVED:'SAVED'}[status]);
 const card=(title,status,values,alert=false)=>'<article class="window-metric '+status.toLowerCase()+(alert?' needs-attention':'')+'">'+(alert?'<span class="attention-badge" role="img" aria-label="Review: large difference from comps" title="Large difference from comps — review this setting">!</span>':metricIcon(title))+'<div><h3>'+title.replace(/^[★＋▤☾$]\s*/,'')+'</h3><b>'+(alert?(status==='SAVED'?'REVIEW':label(status)+' · REVIEW'):label(status))+'</b></div><strong>'+values+'</strong></article>';
 const entries=[{label:'Your property',name:p.name,profile:ratingProfile(ownAirbnbId(p))},...view.comps.map((c,index)=>({label:'Comp '+(index+1),name:c.name||c.id,profile:ratingProfile(c.id,c.name)}))];
 const ranks=PricingMath.ratingRanks(entries.map(entry=>entry.profile.rating)),placeLabel=rank=>rank===1?'1st':rank===2?'2nd':rank===3?'3rd':rank+'th';
 const ratingBox='<section class="ratings-comparison" aria-label="Airbnb ratings for your property and each comp"><h3>★ Airbnb Ratings</h3><div class="rating-columns">'+entries.map((entry,index)=>'<article class="listing-rating '+(index===0?'your-rating':'')+'">'+(ranks[index]===null?'':'<span class="rating-place place-'+ranks[index]+'" aria-label="'+placeLabel(ranks[index])+' place by Airbnb rating"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M7 3h10v5a5 5 0 0 1-10 0V3ZM7 5H3v2a4 4 0 0 0 4 4m10-6h4v2a4 4 0 0 1-4 4m-5 2v5m-4 3h8m-6-3h4"/></svg>'+placeLabel(ranks[index])+'</span>')+'<span class="rating-label">'+entry.label+'</span><span class="rating-property" title="'+esc(entry.name)+'">'+esc(entry.name)+'</span><strong>'+(entry.profile.rating?'★ '+entry.profile.rating.toFixed(2):entry.profile.isNew?'New':'—')+'</strong></article>').join('')+'</div></section>';
 const ownMap=new Map((view.own?.days||[]).map(d=>[d.date,d])),matched=dates.map(date=>{const own=ownMap.get(date),rates=view.comps.map(c=>c.snapshot?.days?.find(d=>d.date===date)).filter(d=>d&&d.available!==false&&Number.isFinite(d.rate)).map(d=>d.rate).sort((a,b)=>a-b);if(!own||own.available===false||!Number.isFinite(own.rate)||!rates.length)return null;const n=rates.length;return {own:own.rate,comp:n%2?rates[(n-1)/2]:(rates[n/2-1]+rates[n/2])/2};}).filter(Boolean),mean=key=>matched.length?matched.reduce((sum,d)=>sum+d[key],0)/matched.length:null;
 const pricing=card('Nightly rates','SAVED','Yours '+fee(mean('own'))+' · Comps '+fee(mean('comp')),PricingMath.needsAttention('rate',mean('own'),mean('comp'))),count=card('Comp set','SAVED',view.comps.length+' comps · '+matched.length+' dates');
 return ratingBox+'<div class="window-metrics">'+pricing+count+card('☾ Minimum nights',stay.status,'Yours '+night(stay.current)+' · Comps '+night(stay.comp)+' nights',PricingMath.needsAttention('stay',stay.current,stay.comp))+card('$ Cleaning fee',clean.status,'Yours '+fee(clean.current)+' · Comps '+fee(clean.comp),PricingMath.needsAttention('cleaning',clean.current,clean.comp))+'<article class="window-metric availability-compact">'+metricIcon('Booked')+'<div><h3>Booked / blocked</h3></div><strong>Yours '+(availability.ownPercent===null?'—':availability.ownPercent.toFixed(0)+'%')+' · Comps '+(availability.compPercent===null?'—':availability.compPercent.toFixed(0)+'%')+'</strong></article></div>';
}
function renderPropertyInsights(p){
 const panel=$('propertyInsights');panel.hidden=!p;if(!p){panel.innerHTML='';return;}
 const view=savedPropertyView(p),dates=popupVisibleDates(),own=view.own?.days||[],periods=String(p.currency||'').toUpperCase()==='USD'?PricingMath.attentionPeriods(dates,own,view.comps):[];
 const shortDate=date=>new Date(date+'T00:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
 panel.innerHTML='<div class="window-summary-heading"><h3>Summary · '+shortDate(dates[0])+' – '+shortDate(dates.at(-1))+'</h3></div>'+windowComparisonCards(p,view,dates)+'<div class="insight-heading"><h3>Priority dates</h3></div><div class="attention-cards">'+(periods.length?periods.map(g=>'<article class="attention-card '+(g.move>0?'increase':'decrease')+'"><button class="attention-date" data-attention-date="'+esc(g.start)+'">'+shortDate(g.start)+(g.end!==g.start?' – '+shortDate(g.end):'')+' ↗</button><strong>'+g.direction+' '+Math.abs(g.move).toFixed(1)+'%</strong><div>'+money(g.current)+' → '+money(g.target)+' / night</div></article>').join(''):'<p class="insight-empty">No major rate gaps on these dates.</p>')+'</div>';
 panel.querySelectorAll('[data-attention-date]').forEach(button=>button.onclick=()=>{$('expandedDate').value=button.dataset.attentionDate;$('expandedDate').onchange();});
}
$('expandAll').onclick=()=>{const box=document.querySelector('.calendar-scroll'),left=box.scrollLeft,top=box.scrollTop;allExpanded=!allExpanded;render();box.scrollLeft=left;box.scrollTop=top;};
$('closeExpanded').onclick=()=>$('expandedDialog').close();
$('expandedDialog').addEventListener('click',event=>{if(event.target!==$('expandedDialog'))return;const rect=$('expandedDialog').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('expandedDialog').close();});
$('expandedDate').onchange=()=>{document.querySelector('.expanded-scroll').scrollLeft=Math.max(0,days().indexOf($('expandedDate').value))*dateColumnWidth;updateVisibleInsights();};
$('expandedToday').onclick=()=>{$('expandedDate').value=today();$('expandedDate').onchange();};
document.querySelector('.expanded-scroll').addEventListener('scroll',()=>{clearTimeout(insightScrollTimer);insightScrollTimer=setTimeout(updateVisibleInsights,100);},{passive:true});
$('expandedDialog').addEventListener('close',()=>{clearTimeout(insightScrollTimer);popupPropertyId=null;});
if(typeof window!=='undefined')window.addEventListener('resize',()=>{clearTimeout(insightScrollTimer);insightScrollTimer=setTimeout(updateVisibleInsights,100);});

function clearRenderKeyFields(){for(const id of ['renderGuestyId','renderGuestySecret','renderAirroiKey'])$(id).value='';}
$('renderKeysForm').onsubmit=async event=>{
 event.preventDefault();const button=$('saveRenderKeys');button.disabled=true;
 const values={guestyClientId:$('renderGuestyId').value,guestyClientSecret:$('renderGuestySecret').value,airroiKey:$('renderAirroiKey').value};
 clearRenderKeyFields();
 try{dialogMessage('renderKeysMessage','Saving to Render…');const result=await post('/render-keys',values);dialogMessage('renderKeysMessage','Saved '+result.saved.length+' value(s) in Render. Deployment started. Wait until Render shows Live, then refresh this page. Blank fields were kept.');}
 catch(error){dialogMessage('renderKeysMessage',error.message,true);}finally{for(const key of Object.keys(values))values[key]='';button.disabled=!state.renderKeyUpdates;}
};
$('settingsDialog').addEventListener('close',clearRenderKeyFields);

if(typeof window!=='undefined')window.addEventListener('pageshow',event=>{if(event.persisted&&state.hosted)window.location.reload();});

function openApiSettings(){settingsButton.click();document.querySelector('.render-key-settings').open=true;}

function renderChannels(p){$('channelLinks').innerHTML=['airbnb','vrbo'].filter(k=>p?.channelLinks?.[k]).map(k=>'<a target="_blank" rel="noopener noreferrer" href="'+esc(p.channelLinks[k])+'">'+(k==='airbnb'?'Airbnb':'Vrbo')+' ↗</a>').join(' · ');}
$('previousProperty').onclick=()=>task($('previousProperty'),async()=>{const list=properties(),index=list.findIndex(p=>p.id===popupPropertyId),box=document.querySelector('.expanded-scroll'),left=box.scrollLeft;await openCalendarWindow(list[(index-1+list.length)%list.length].id);box.scrollLeft=left;updateVisibleInsights();});
$('nextProperty').onclick=()=>task($('nextProperty'),async()=>{const list=properties(),index=list.findIndex(p=>p.id===popupPropertyId),box=document.querySelector('.expanded-scroll'),left=box.scrollLeft;await openCalendarWindow(list[(index+1)%list.length].id);box.scrollLeft=left;updateVisibleInsights();});
$('saveOwnAirbnb').onclick=()=>task($('saveOwnAirbnb'),async()=>{state=await post('/property-link',{propertyId:selected,url:$('ownAirbnbUrl').value});await loadSavedOwn();dialogMessage('compMessage','Your Airbnb link is saved.');});

$('updateRatings').onclick=()=>task($('updateRatings'),async()=>{let job=await post('/ratings-update',{});while(job.status==='running'){ $('updateRatings').textContent=job.phase+' · '+job.processed+'/'+job.total;await new Promise(resolve=>setTimeout(resolve,1200));job=await api('/ratings-update');}await refreshState();await loadSavedOwn();if($('expandedDialog').open){const left=document.querySelector('.expanded-scroll').scrollLeft;renderExpandedCalendar(popupPropertyId);renderChannels(properties().find(p=>p.id===popupPropertyId));document.querySelector('.expanded-scroll').scrollLeft=left;updateVisibleInsights();}notice('Ratings: '+job.saved+' collected · '+job.reused+' reused.'+(job.errors.length?' '+job.errors.join(' '):''));}).finally(()=>{$('updateRatings').textContent='★ Update links & ratings';});
